--
-- Name: haversinedistance(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: developer
--

CREATE FUNCTION public.haversinedistance(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision) RETURNS double precision
    LANGUAGE plpgsql
    AS $$

      DECLARE

        R FLOAT = 6371; -- Earth radius in kilometers

        dlat FLOAT;

        dlon FLOAT;

        a FLOAT;

        c FLOAT;

      BEGIN

        dlat := RADIANS(lat2 - lat1);

        dlon := RADIANS(lon2 - lon1);

        a := SIN(dlat / 2) * SIN(dlat / 2) + COS(RADIANS(lat1)) * COS(RADIANS(lat2)) * SIN(dlon / 2) * SIN(dlon / 2);

        c := 2 * ATAN2(SQRT(a), SQRT(1 - a));

        RETURN R * c;

      END;

      $$;


ALTER FUNCTION public.haversinedistance(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision) OWNER TO developer;

--
-- Name: update_product_review_stats(); Type: FUNCTION; Schema: public; Owner: developer
--

CREATE FUNCTION public.update_product_review_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

      DECLARE

          newAverage DECIMAL(3, 2);

          newCount INT;

      BEGIN

          -- Select the new average rating and count of reviews for the product

          SELECT AVG(rating), COUNT(*)

          INTO newAverage, newCount

          FROM "PRODUCT_REVIEWS"

          WHERE "product_id" = NEW.product_id;

          -- Update the PRODUCTS table with the new average rating and review count

          UPDATE "PRODUCTS"

          SET "averageRating" = newAverage, "totalReviews" = newCount

          WHERE _id = NEW.product_id;

          -- Return the new row

          RETURN NEW;

      END;

      $$;


ALTER FUNCTION public.update_product_review_stats() OWNER TO developer;

